func appPostRides(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	req := &appPostRidesRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.PickupCoordinate == nil || req.DestinationCoordinate == nil {
		writeError(w, http.StatusBadRequest, errors.New("required fields(pickup_coordinate, destination_coordinate) are empty"))
		return
	}

	user := ctx.Value("user").(*User)
	rideID := ulid.Make().String()

	tx, err := db.Beginx()
	if err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}
	defer tx.Rollback()

	var continuingRideCount int
	if err := tx.GetContext(ctx, &continuingRideCount, `SELECT COUNT(*) FROM rides WHERE user_id = ? AND status <> 'COMPLETED'`, user.ID); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}
	if continuingRideCount > 0 {
		writeError(w, http.StatusConflict, errors.New("ride already exists"))
		return
	}

	var coupon Coupon
	hasCoupon := true
	if err := tx.GetContext(ctx, &coupon, `SELECT * FROM coupons WHERE user_id = ? AND used_by IS NULL ORDER BY CASE WHEN code = 'CP_NEW2024' THEN 0 ELSE 1 END, created_at ASC, code ASC LIMIT 1 FOR UPDATE`, user.ID); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			hasCoupon = false
		} else {
			writeError(w, http.StatusInternalServerError, err)
			return
		}
	}

	discount := 0
	if hasCoupon {
		discount = coupon.Discount
	}
	baseFare := calculateFare(req.PickupCoordinate.Latitude, req.PickupCoordinate.Longitude, req.DestinationCoordinate.Latitude, req.DestinationCoordinate.Longitude)
	fare := initialFare + max(baseFare-initialFare-discount, 0)

	if _, err := tx.ExecContext(
		ctx,
		`INSERT INTO rides (id, user_id, pickup_latitude, pickup_longitude, destination_latitude, destination_longitude, fare, status)
		 VALUES (?, ?, ?, ?, ?, ?, ?, 'MATCHING')`,
		rideID, user.ID, req.PickupCoordinate.Latitude, req.PickupCoordinate.Longitude, req.DestinationCoordinate.Latitude, req.DestinationCoordinate.Longitude, fare,
	); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	if _, err := tx.ExecContext(
		ctx,
		`INSERT INTO ride_statuses (id, ride_id, status) VALUES (?, ?, ?)`,
		ulid.Make().String(), rideID, "MATCHING",
	); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	if hasCoupon {
		if _, err := tx.ExecContext(
			ctx,
			"UPDATE coupons SET used_by = ? WHERE user_id = ? AND code = ?",
			rideID, user.ID, coupon.Code,
		); err != nil {
			writeError(w, http.StatusInternalServerError, err)
			return
		}
	}

	if err := tx.Commit(); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	wakeMatcher()

	writeJSON(w, http.StatusAccepted, &appPostRidesResponse{
		RideID: rideID,
		Fare:   fare,
	})
}

