func appGetNearbyChairs(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	latStr := r.URL.Query().Get("latitude")
	lonStr := r.URL.Query().Get("longitude")
	distanceStr := r.URL.Query().Get("distance")
	if latStr == "" || lonStr == "" {
		writeError(w, http.StatusBadRequest, errors.New("latitude or longitude is empty"))
		return
	}

	lat, err := strconv.Atoi(latStr)
	if err != nil {
		writeError(w, http.StatusBadRequest, errors.New("latitude is invalid"))
		return
	}

	lon, err := strconv.Atoi(lonStr)
	if err != nil {
		writeError(w, http.StatusBadRequest, errors.New("longitude is invalid"))
		return
	}

	distance := 50
	if distanceStr != "" {
		distance, err = strconv.Atoi(distanceStr)
		if err != nil {
			writeError(w, http.StatusBadRequest, errors.New("distance is invalid"))
			return
		}
	}

	rows := []nearbyChairRow{}
	if err := db.SelectContext(ctx, &rows, `
SELECT c.id, c.name, c.model, cl.latitude, cl.longitude
FROM chairs c
JOIN chair_locations cl ON cl.id = (
  SELECT cl2.id FROM chair_locations cl2
  WHERE cl2.chair_id = c.id
  ORDER BY cl2.created_at DESC, cl2.id DESC
  LIMIT 1
)
WHERE c.is_active = TRUE
  AND c.current_ride_id IS NULL
  AND ABS(cl.latitude - ?) + ABS(cl.longitude - ?) <= ?`,
		lat, lon, distance); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	nearbyChairs := make([]appGetNearbyChairsResponseChair, 0, len(rows))
	for _, row := range rows {
		nearbyChairs = append(nearbyChairs, appGetNearbyChairsResponseChair{
			ID:    row.ID,
			Name:  row.Name,
			Model: row.Model,
			CurrentCoordinate: Coordinate{
				Latitude:  row.Latitude,
				Longitude: row.Longitude,
			},
		})
	}

	var retrievedAt time.Time
	if err := db.GetContext(ctx, &retrievedAt, `SELECT CURRENT_TIMESTAMP(6)`); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	writeJSON(w, http.StatusOK, &appGetNearbyChairsResponse{
		Chairs:      nearbyChairs,
		RetrievedAt: retrievedAt.UnixMilli(),
	})
}

func calculateFare(pickupLatitude, pickupLongitude, destLatitude, destLongitude int) int {
	meteredFare := farePerDistance * calculateDistance(pickupLatitude, pickupLongitude, destLatitude, destLongitude)
	return initialFare + meteredFare
}

func calculateDiscountedFare(ctx context.Context, q executableGet, userID string, ride *Ride, pickupLatitude, pickupLongitude, destLatitude, destLongitude int) (int, error) {
	var coupon Coupon
	discount := 0
	if ride != nil {
		destLatitude = ride.DestinationLatitude
		destLongitude = ride.DestinationLongitude
		pickupLatitude = ride.PickupLatitude
		pickupLongitude = ride.PickupLongitude

		if err := q.GetContext(ctx, &coupon, "SELECT * FROM coupons WHERE used_by = ? LIMIT 1", ride.ID); err != nil {
			if !errors.Is(err, sql.ErrNoRows) {
				return 0, err
			}
		} else {
			discount = coupon.Discount
		}
	} else {
		if err := q.GetContext(ctx, &coupon, "SELECT * FROM coupons WHERE user_id = ? AND used_by IS NULL ORDER BY CASE WHEN code = 'CP_NEW2024' THEN 0 ELSE 1 END, created_at ASC, code ASC LIMIT 1", userID); err != nil {
			if !errors.Is(err, sql.ErrNoRows) {
				return 0, err
			}
		} else {
			discount = coupon.Discount
		}
	}

	meteredFare := farePerDistance * calculateDistance(pickupLatitude, pickupLongitude, destLatitude, destLongitude)
	discountedMeteredFare := max(meteredFare-discount, 0)

	return initialFare + discountedMeteredFare, nil
}
