	PickupLongitude      int    `db:"pickup_longitude"`
	DestinationLatitude  int    `db:"destination_latitude"`
	DestinationLongitude int    `db:"destination_longitude"`
}

func ownerGetSales(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	since := time.Unix(0, 0)
	until := time.Date(9999, 12, 31, 23, 59, 59, 0, time.UTC)
	if r.URL.Query().Get("since") != "" {
		parsed, err := strconv.ParseInt(r.URL.Query().Get("since"), 10, 64)
		if err != nil {
			writeError(w, http.StatusBadRequest, err)
			return
		}
		since = time.UnixMilli(parsed)
	}
	if r.URL.Query().Get("until") != "" {
		parsed, err := strconv.ParseInt(r.URL.Query().Get("until"), 10, 64)
		if err != nil {
			writeError(w, http.StatusBadRequest, err)
			return
		}
		until = time.UnixMilli(parsed)
	}

	owner := r.Context().Value("owner").(*Owner)

	chairs := []ownerSalesChairRow{}
	if err := db.SelectContext(ctx, &chairs, "SELECT id, name, model FROM chairs WHERE owner_id = ? ORDER BY id", owner.ID); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	rides := []ownerSalesRideRow{}
	if err := db.SelectContext(ctx, &rides, `
SELECT c.id AS chair_id,
       r.pickup_latitude,
       r.pickup_longitude,
       r.destination_latitude,
       r.destination_longitude
FROM chairs c
JOIN rides r ON r.chair_id = c.id
WHERE c.owner_id = ?
  AND r.status = 'COMPLETED'
  AND r.updated_at BETWEEN ? AND ? + INTERVAL 999 MICROSECOND`, owner.ID, since, until); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	salesByChair := make(map[string]int, len(chairs))
	totalSales := 0
	for _, ride := range rides {
		sales := calculateFare(ride.PickupLatitude, ride.PickupLongitude, ride.DestinationLatitude, ride.DestinationLongitude)
		salesByChair[ride.ChairID] += sales
		totalSales += sales
	}

	res := ownerGetSalesResponse{
		TotalSales: totalSales,
		Chairs:     make([]chairSales, 0, len(chairs)),
	}
	modelSalesByModel := map[string]int{}
	for _, chair := range chairs {
		sales := salesByChair[chair.ID]
		res.Chairs = append(res.Chairs, chairSales{
			ID:    chair.ID,
			Name:  chair.Name,
			Sales: sales,
		})
		modelSalesByModel[chair.Model] += sales
	}

	models := make([]modelSales, 0, len(modelSalesByModel))
	for model, sales := range modelSalesByModel {
		models = append(models, modelSales{
			Model: model,
			Sales: sales,
		})
	}
	res.Models = models

	writeJSON(w, http.StatusOK, res)
}

