	TotalSales int          `json:"total_sales"`
	Chairs     []chairSales `json:"chairs"`
	Models     []modelSales `json:"models"`
}

type ownerSalesChairRow struct {
	ID    string `db:"id"`
	Name  string `db:"name"`
	Model string `db:"model"`
}

type ownerSalesRideRow struct {
	ChairID              string `db:"chair_id"`
	PickupLatitude       int    `db:"pickup_latitude"`
	PickupLongitude      int    `db:"pickup_longitude"`
	DestinationLatitude  int    `db:"destination_latitude"`
	DestinationLongitude int    `db:"destination_longitude"`
}

func ownerGetSales(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	since := time.Unix(0, 0)
	until := time.Date(9999, 12, 31, 23, 59, 59, 0, time.UTC)
	if r.URL.Query().Get("since") != "" {
		parsed, err := strconv.ParseInt(r.URL.Query().Get("since"), 10, 64)
		if err != nil {
			writeError(w, http.StatusBadRequest, err)
			return
		}
		since = time.UnixMilli(parsed)
	}
	if r.URL.Query().Get("until") != "" {
		parsed, err := strconv.ParseInt(r.URL.Query().Get("until"), 10, 64)
		if err != nil {
			writeError(w, http.StatusBadRequest, err)
			return
		}
		until = time.UnixMilli(parsed)
	}

	owner := r.Context().Value("owner").(*Owner)

	chairs := []ownerSalesChairRow{}
	if err := db.SelectContext(ctx, &chairs, "SELECT id, name, model FROM chairs WHERE owner_id = ? ORDER BY id", owner.ID); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	rides := []ownerSalesRideRow{}
	if err := db.SelectContext(ctx, &rides, `
SELECT c.id AS chair_id,
       r.pickup_latitude,
       r.pickup_longitude,
       r.destination_latitude,
       r.destination_longitude
FROM chairs c
JOIN rides r ON r.chair_id = c.id
WHERE c.owner_id = ?
  AND r.status = 'COMPLETED'
  AND r.updated_at BETWEEN ? AND ? + INTERVAL 999 MICROSECOND`, owner.ID, since, until); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	salesByChair := make(map[string]int, len(chairs))
	totalSales := 0
	for _, ride := range rides {
		sales := calculateFare(ride.PickupLatitude, ride.PickupLongitude, ride.DestinationLatitude, ride.DestinationLongitude)
		salesByChair[ride.ChairID] += sales
		totalSales += sales
	}

	res := ownerGetSalesResponse{
		TotalSales: totalSales,
		Chairs:     make([]chairSales, 0, len(chairs)),
	}
	modelSalesByModel := map[string]int{}
	for _, chair := range chairs {
		sales := salesByChair[chair.ID]
		res.Chairs = append(res.Chairs, chairSales{
			ID:    chair.ID,
			Name:  chair.Name,
			Sales: sales,
		})
		modelSalesByModel[chair.Model] += sales
	}

	models := make([]modelSales, 0, len(modelSalesByModel))
	for model, sales := range modelSalesByModel {
		models = append(models, modelSales{
			Model: model,
			Sales: sales,
		})
	}
	res.Models = models

	writeJSON(w, http.StatusOK, res)
}

type chairWithDetail struct {
	ID                     string       `db:"id"`
	OwnerID                string       `db:"owner_id"`
	Name                   string       `db:"name"`
	AccessToken            string       `db:"access_token"`
	Model                  string       `db:"model"`
	IsActive               bool         `db:"is_active"`
	CreatedAt              time.Time    `db:"created_at"`
	UpdatedAt              time.Time    `db:"updated_at"`
	TotalDistance          int          `db:"total_distance"`
	TotalDistanceUpdatedAt sql.NullTime `db:"total_distance_updated_at"`
}

type ownerGetChairResponse struct {
	Chairs []ownerGetChairResponseChair `json:"chairs"`
}

type ownerGetChairResponseChair struct {
	ID                     string `json:"id"`
	Name                   string `json:"name"`
	Model                  string `json:"model"`
	Active                 bool   `json:"active"`
	RegisteredAt           int64  `json:"registered_at"`
	TotalDistance          int    `json:"total_distance"`
	TotalDistanceUpdatedAt *int64 `json:"total_distance_updated_at,omitempty"`
}

func ownerGetChairs(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	owner := ctx.Value("owner").(*Owner)

	chairs := []chairWithDetail{}
	if err := db.SelectContext(ctx, &chairs, `SELECT id,
       owner_id,
       name,
       access_token,
       model,
       is_active,
       created_at,
       updated_at,
       IFNULL(total_distance, 0) AS total_distance,
       total_distance_updated_at
FROM chairs
WHERE owner_id = ?
ORDER BY id`, owner.ID); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	res := ownerGetChairResponse{Chairs: make([]ownerGetChairResponseChair, 0, len(chairs))}
	for _, chair := range chairs {
		c := ownerGetChairResponseChair{
			ID:            chair.ID,
			Name:          chair.Name,
			Model:         chair.Model,
			Active:        chair.IsActive,
			RegisteredAt:  chair.CreatedAt.UnixMilli(),
			TotalDistance: chair.TotalDistance,
		}
		if chair.TotalDistanceUpdatedAt.Valid {
			t := chair.TotalDistanceUpdatedAt.Time.UnixMilli()
			c.TotalDistanceUpdatedAt = &t
		}
		res.Chairs = append(res.Chairs, c)
	}
	writeJSON(w, http.StatusOK, res)
}
