func matchPendingRides(ctx context.Context) {
	rides := []Ride{}
	if err := db.SelectContext(ctx, &rides, `SELECT * FROM rides WHERE chair_id IS NULL ORDER BY created_at ASC LIMIT 100`); err != nil || len(rides) == 0 {
		return
	}

	chairs := []availableChair{}
	if err := db.SelectContext(ctx, &chairs, `
SELECT c.id, cm.speed, cl.latitude, cl.longitude
FROM chairs c
JOIN chair_models cm ON cm.name = c.model
JOIN chair_locations cl ON cl.id = (
  SELECT cl2.id FROM chair_locations cl2
  WHERE cl2.chair_id = c.id
  ORDER BY cl2.created_at DESC, cl2.id DESC
  LIMIT 1
)
