package main

import (
	"context"
	"math"
	"net/http"
	"time"
)

type availableChair struct {
	ID        string `db:"id"`
	Speed     int    `db:"speed"`
	Latitude  int    `db:"latitude"`
	Longitude int    `db:"longitude"`
}

func wakeMatcher() {
	select {
	case matchWake <- struct{}{}:
	default:
	}
}

func matcherLoop() {
	ticker := time.NewTicker(50 * time.Millisecond)
	defer ticker.Stop()
	for {
		select {
		case <-matchWake:
		case <-ticker.C:
		}
		if initializing.Load() {
			continue
		}
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		matchPendingRides(ctx)
		cancel()
	}
}

func internalGetMatching(w http.ResponseWriter, r *http.Request) {
	if !initializing.Load() {
		ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
		matchPendingRides(ctx)
		cancel()
	}
	w.WriteHeader(http.StatusNoContent)
}

func matchPendingRides(ctx context.Context) {
	rides := []Ride{}
	if err := db.SelectContext(ctx, &rides, `SELECT * FROM rides WHERE chair_id IS NULL ORDER BY created_at ASC LIMIT 100`); err != nil || len(rides) == 0 {
		return
	}

	chairs := []availableChair{}
	if err := db.SelectContext(ctx, &chairs, `
SELECT c.id, cm.speed, cl.latitude, cl.longitude
FROM chairs c
JOIN chair_models cm ON cm.name = c.model
JOIN chair_locations cl ON cl.id = (
  SELECT cl2.id FROM chair_locations cl2
  WHERE cl2.chair_id = c.id
  ORDER BY cl2.created_at DESC, cl2.id DESC
  LIMIT 1
)
WHERE c.is_active = TRUE
  AND c.current_ride_id IS NULL`); err != nil || len(chairs) == 0 {
		return
	}

	used := make(map[string]bool, len(chairs))
	for _, ride := range rides {
		bestIndex := -1
		bestTime := math.MaxFloat64
		bestDistance := math.MaxInt32
		rideDistance := abs(ride.PickupLatitude-ride.DestinationLatitude) + abs(ride.PickupLongitude-ride.DestinationLongitude)
		for i, chair := range chairs {
			if used[chair.ID] || chair.Speed <= 0 {
				continue
			}
			pickupDistance := abs(chair.Latitude-ride.PickupLatitude) + abs(chair.Longitude-ride.PickupLongitude)
			estimatedTime := float64(pickupDistance+rideDistance) / float64(chair.Speed)
			if estimatedTime < bestTime || (estimatedTime == bestTime && pickupDistance < bestDistance) {
				bestIndex = i
				bestTime = estimatedTime
				bestDistance = pickupDistance
			}
		}
		if bestIndex < 0 {
			break
		}

		chair := chairs[bestIndex]
		tx, err := db.BeginTxx(ctx, nil)
		if err != nil {
			return
		}

		result, err := tx.ExecContext(ctx, `UPDATE rides SET chair_id = ? WHERE id = ? AND chair_id IS NULL`, chair.ID, ride.ID)
		if err != nil {
			tx.Rollback()
			continue
		}
		affected, err := result.RowsAffected()
		if err != nil || affected == 0 {
			tx.Rollback()
			continue
		}

		result, err = tx.ExecContext(ctx, `UPDATE chairs SET current_ride_id = ? WHERE id = ? AND current_ride_id IS NULL`, ride.ID, chair.ID)
		if err != nil {
			tx.Rollback()
			continue
		}
		affected, err = result.RowsAffected()
		if err != nil || affected == 0 {
			tx.Rollback()
			continue
		}

		if err := tx.Commit(); err != nil {
			continue
		}
		used[chair.ID] = true
	}
}
