{"command":"ssh s1 'sudo mysql isuride -e "
SELECT COUNT(*) AS mismatches FROM chairs c JOIN (
  SELECT chair_id, SUM(IFNULL(distance,0)) total_distance, MAX(created_at) updated_at FROM (
    SELECT chair_id, created_at, ABS(latitude - LAG(latitude) OVER (PARTITION BY chair_id ORDER BY created_at)) + ABS(longitude - LAG(longitude) OVER (PARTITION BY chair_id ORDER BY created_at)) AS distance
    FROM chair_locations
  ) t GROUP BY chair_id
) d ON d.chair_id=c.id
WHERE c.total_distance <> d.total_distance OR NOT (c.total_distance_updated_at <=> d.updated_at);
SELECT COUNT(*) FROM (SELECT chair_id,created_at,COUNT(*) c FROM chair_locations GROUP BY chair_id,created_at HAVING c>1) x;
"' 2>&1","description":"Compare stored total distance to reference window query"}

