	}
	if err == nil {
		status = yetSentRideStatus.Status
	}

	user := &User{}
	if err := tx.GetContext(ctx, user, "SELECT id, firstname, lastname FROM users WHERE id = ?", ride.UserID); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	completedSent := false
	if yetSentRideStatus.ID != "" {
		if _, err := tx.ExecContext(ctx, `UPDATE ride_statuses SET chair_sent_at = CURRENT_TIMESTAMP(6) WHERE id = ? AND chair_sent_at IS NULL`, yetSentRideStatus.ID); err != nil {
			writeError(w, http.StatusInternalServerError, err)
			return
		}
		if yetSentRideStatus.Status == "COMPLETED" {
			if _, err := tx.ExecContext(ctx, `UPDATE chairs SET current_ride_id = NULL WHERE id = ? AND current_ride_id = ?`, chair.ID, ride.ID); err != nil {
				writeError(w, http.StatusInternalServerError, err)
				return
			}
			completedSent = true
		}
	}

	if err := tx.Commit(); err != nil {
		writeError(w, http.StatusInternalServerError, err)
		return
	}
	if completedSent {
		wakeMatcher()
	}

	writeJSON(w, http.StatusOK, &chairGetNotificationResponse{
		Data: &chairGetNotificationResponseData{
			RideID: ride.ID,
			User: simpleUser{
				ID:   user.ID,
				Name: fmt.Sprintf("%s %s", user.Firstname, user.Lastname),
			},
			PickupCoordinate: Coordinate{
				Latitude:  ride.PickupLatitude,
				Longitude: ride.PickupLongitude,
			},
			DestinationCoordinate: Coordinate{
				Latitude:  ride.DestinationLatitude,
				Longitude: ride.DestinationLongitude,
			},
			Status: status,
		},
		RetryAfterMs: 30,
	})
}

'''
