new='''type appNotificationRow struct {
	RideID              string         `db:"ride_id"`
	UserID              string         `db:"user_id"`
	PickupLatitude      int            `db:"pickup_latitude"`
	PickupLongitude     int            `db:"pickup_longitude"`
	DestinationLatitude int            `db:"destination_latitude"`
	DestinationLongitude int           `db:"destination_longitude"`
	Fare                int            `db:"fare"`
	RideStatus          string         `db:"ride_status"`
	CreatedAt           time.Time      `db:"created_at"`
	UpdatedAt           time.Time      `db:"updated_at"`
	ChairID             sql.NullString `db:"chair_id"`
	ChairName           sql.NullString `db:"chair_name"`
	ChairModel          sql.NullString `db:"chair_model"`
	TotalRidesCount     sql.NullInt64  `db:"total_rides_count"`
	TotalEvaluationSum  sql.NullInt64  `db:"total_evaluation_sum"`
	StatusID            sql.NullString `db:"status_id"`
	NotifStatus         sql.NullString `db:"notif_status"`
}

func appGetNotification(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	user := ctx.Value("user").(*User)

	row := appNotificationRow{}
	err := db.GetContext(ctx, &row, `
SELECT r.id AS ride_id,
       r.user_id,
       r.pickup_latitude,
       r.pickup_longitude,
       r.destination_latitude,
       r.destination_longitude,
       r.fare,
       r.status AS ride_status,
       r.created_at,
       r.updated_at,
       r.chair_id,
       c.name AS chair_name,
       c.model AS chair_model,
       c.total_rides_count,
       c.total_evaluation_sum,
       s.id AS status_id,
       s.status AS notif_status
FROM rides r
LEFT JOIN chairs c ON c.id = r.chair_id
LEFT JOIN ride_statuses s ON s.id = (
  SELECT s2.id FROM ride_statuses s2
  WHERE s2.ride_id = r.id AND s2.app_sent_at IS NULL
  ORDER BY s2.created_at ASC
  LIMIT 1
)
WHERE r.user_id = ?
ORDER BY r.created_at DESC
LIMIT 1`, user.ID)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeJSON(w, http.StatusOK, &appGetNotificationResponse{
				RetryAfterMs: retryAfterMs,
			})
			return
		}
		writeError(w, http.StatusInternalServerError, err)
		return
	}

	status := row.RideStatus
	if row.NotifStatus.Valid {
		status = row.NotifStatus.String
	}

	response := &appGetNotificationResponse{
		Data: &appGetNotificationResponseData{
			RideID: row.RideID,
			PickupCoordinate: Coordinate{
				Latitude:  row.PickupLatitude,
				Longitude: row.PickupLongitude,
			},
			DestinationCoordinate: Coordinate{
				Latitude:  row.DestinationLatitude,
				Longitude: row.DestinationLongitude,
			},
			Fare:      row.Fare,
			Status:    status,
			CreatedAt: row.CreatedAt.UnixMilli(),
			UpdateAt:  row.UpdatedAt.UnixMilli(),
		},
		RetryAfterMs: retryAfterMs,
	}

	if row.ChairID.Valid {
		stats := appGetNotificationResponseChairStats{
			TotalRidesCount: int(row.TotalRidesCount.Int64),
		}
		if row.TotalRidesCount.Int64 > 0 {
			stats.TotalEvaluationAvg = float64(row.TotalEvaluationSum.Int64) / float64(row.TotalRidesCount.Int64)
		}
		response.Data.Chair = &appGetNotificationResponseChair{
			ID:    row.ChairID.String,
			Name:  row.ChairName.String,
			Model: row.ChairModel.String,
			Stats: stats,
		}
	}

	if row.StatusID.Valid {
		if _, err := db.ExecContext(ctx, `UPDATE ride_statuses SET app_sent_at = CURRENT_TIMESTAMP(6) WHERE id = ? AND app_sent_at IS NULL`, row.StatusID.String); err != nil {
			writeError(w, http.StatusInternalServerError, err)
			return
		}
	}

	writeJSON(w, http.StatusOK, response)
}

