EXPLAIN ANALYZE SELECT q.*, u.firstname AS user_firstname, u.lastname AS user_lastname FROM (SELECT r.id AS ride_id,r.user_id,r.pickup_latitude,r.pickup_longitude,r.destination_latitude,r.destination_longitude,r.status AS ride_status,r.created_at,s.id AS status_id,s.status AS notif_status FROM rides r LEFT JOIN ride_statuses s ON s.id=(SELECT s2.id FROM ride_statuses s2 WHERE s2.ride_id=r.id AND s2.chair_sent_at IS NULL ORDER BY s2.created_at ASC LIMIT 1) WHERE r.chair_id=(SELECT chair_id FROM rides WHERE chair_id IS NOT NULL LIMIT 1) ORDER BY r.created_at DESC,r.id DESC LIMIT 1) q JOIN users u ON u.id=q.user_id;
"' 2>&1 | sed 's/\\n/\n/g' | head -120","description":"Test forcing chair notification join order"}

