{"command":"for h in s1 s2 s3; do scp $h:/tmp/vmstat_run8.txt /tmp/vmstat_run8_$h.txt >/dev/null 2>&1; done
python3 - <<'PY'
import glob,statistics
for f in sorted(glob.glob('/tmp/vmstat_run8_s*.txt')):
    rows=[]
    for line in open(f):
        p=line.split()
        if len(p)>=17 and p[0].isdigit(): rows.append(p)
    hi=[r for r in rows if int(r[14])<90]
    print(f,'samples',len(rows),'hi',len(hi))
    if hi:
        for idx,name in [(0,'r'),(12,'us'),(13,'sy'),(14,'id'),(15,'wa')]:
            vals=[int(r[idx]) for r in hi]
            print(' ',name,'avg',round(statistics.mean(vals),1),'max',max(vals))
    print(' timeline:', ' '.join(f"{r[12]}/{r[13]}/{r[14]}" for r in rows[3:75:5]))
PY","description":"Analyze CPU utilization for run8"}

