import json,ssl,urllib.request,urllib.error,http.cookiejar
BASE='https://127.0.0.1'; ctx=ssl._create_unverified_context()
class C:
 def __init__(self): self.op=urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()),urllib.request.HTTPSHandler(context=ctx))
 def req(self,m,p,d=None):
  b=json.dumps(d).encode() if d is not None else None
  h={'Host':'isuride.xiv.isucon.net'}
  if b: h['Content-Type']='application/json'
  r=urllib.request.Request(BASE+p,data=b,headers=h,method=m)
  try:
   with self.op.open(r,timeout=15) as x:
    z=x.read(); return x.status,(json.loads(z) if z else None)
  except urllib.error.HTTPError as e:
   z=e.read(); return e.code,(json.loads(z) if z else None)
own=C(); _,o=own.req('POST','/api/owner/owners',{'name':'DistTestOwner'})
ch=C(); _,c=ch.req('POST','/api/chair/chairs',{'name':'DistTestChair','model':'クエストチェア Lite','chair_register_token':o['chair_register_token']})
ch.req('POST','/api/chair/activity',{'is_active':True})
def dist():
 code,r=own.req('GET','/api/owner/chairs')
 for x in r['chairs']:
  if x['id']==c['id']: return x['total_distance']
for coord,exp in [((0,0),0),((3,4),0),((3,10),6),((10,10),13)]:
 ch.req('POST','/api/chair/coordinate',{'latitude':coord[0],'longitude':coord[1]})
 print(coord,dist(),'expect',exp)
print('DIST_TEST_OK')
PY
